// ── Recebe records do Airtable e gera Pitch_Script personalizado ──────────
const response  = $input.first().json;
const records   = response.records || [];

if (records.length === 0) {
  return [{ json: { _sem_leads: true, total: 0 } }];
}

const TEMPLATES = [
  // Template A — foco em identidade visual
  (nome, nicho, cidade) =>
    `Oi ${nome}! Vi que vocês atuam com ${nicho} aqui em ${cidade} e adorei o perfil! 🔥\n\n` +
    `Tenho trabalhado com empresas do mesmo segmento e percebi que muitas ainda não têm uma ` +
    `identidade visual que realmente transmite profissionalismo e converte clientes.\n\n` +
    `Posso te mostrar alguns cases do meu trabalho? São 5 minutinhos. 🙏`,

  // Template B — foco em problema percebido
  (nome, nicho, cidade) =>
    `Olá ${nome}! Encontrei o perfil de vocês no Instagram — trabalho com ${nicho} em ${cidade} e ` +
    `fiquei curioso sobre a presença de marca de vocês. 🎨\n\n` +
    `Tenho ajudado empresas a aumentarem a percepção de valor com identidade visual profissional. ` +
    `Vale uma conversa rápida?`,

  // Template C — prova social + urgência
  (nome, nicho, cidade) =>
    `Oi ${nome}! Sou designer especializado em ${nicho} em ${cidade} — acabei de entregar um projeto ` +
    `para uma empresa do seu segmento e os resultados foram ótimos! 🚀\n\n` +
    `Vocês já pensaram em investir em identidade visual? Tenho uma janela essa semana. 📅`
];

const result = [];

for (const record of records) {
  const f = record.fields || {};
  const nome   = (f.Nome_Empresa || f.Username || 'Olá').split(' ')[0];
  const nicho  = f.Nicho  || 'seu segmento';
  const cidade = f.Cidade || 'sua cidade';
  const score  = f.Lead_Score || 0;

  // Roda os templates ciclicamente por score para variar o copy
  const templateIdx = score % TEMPLATES.length;
  const pitchScript = TEMPLATES[templateIdx](nome, nicho, cidade);

  result.push({
    json: {
      record_id:    record.id,
      Username:     f.Username,
      Nome_Empresa: f.Nome_Empresa,
      Telefone_WA:  f.Telefone_WA,
      Lead_Score:   score,
      Pitch_Script: pitchScript
    }
  });
}

console.log(`[MOD4] ${result.length} leads prontos para pipeline.`);
return result;

